import json
import csv

# Load zip codes and find Illinois ones
with open('json/zip_code.json', 'r') as f:
    zip_data = json.load(f)

illinois_zips = set()
for record in zip_data['records']:
    if record.get('state') == 'Illinois':
        illinois_zips.add(record['zip_code'])

print(f"Found {len(illinois_zips)} Illinois zip codes")
print(f"Sample IL zip codes: {list(illinois_zips)[:10]}")

# Load members and filter for Illinois
illinois_members = []
with open('csv/member.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        zip_val = row.get('zip', '')
        # Convert to int for comparison
        try:
            if int(zip_val) in illinois_zips:
                illinois_members.append({
                    'first_name': row['first_name'],
                    'last_name': row['last_name']
                })
        except (ValueError, TypeError):
            pass

print(f"Found {len(illinois_members)} members from Illinois")
for m in illinois_members:
    print(f"{m['first_name']} {m['last_name']}")

